1	import Phaser from 'phaser';
2	import { RELEASE_NOTES } from '../data/releaseNotes';
3	import BaseScene from './BaseScene';
4	
5	export default class ReleaseNotesScene extends BaseScene {
6	  private scrollContainer!: Phaser.GameObjects.Container;
7	  private maskShape!: Phaser.GameObjects.Graphics;
8	  private scrollY: number = 0;
9	  private maxScrollY: number = 0;
10	  private isDragging: boolean = false;
11	  private dragStartY: number = 0;
12	  private dragStartScrollY: number = 0;
13	
14	  constructor() {
15	    super('ReleaseNotesScene');
16	  }
17	
18	  preload() {
19	    if (!this.textures.exists('background2')) {
20	      this.load.image('background2', 'assets/backgrounds/background2.webp');
21	    }
22	  }
23	
24	  create() {
25	    super.create();
26	
27	    const W = this.scale.width;
28	    const H = this.scale.height;
29	    const cx = W / 2;
30	    const yOff = (H - 600) / 2;
31	    const scrollTop = 70 + yOff;
32	    const scrollBottom = H - 60; // 뒤로가기 버튼 위
33	    const scrollHeight = scrollBottom - scrollTop;
