  'wp_gold_mine:miner': { label: '황금 광산 × 광부', ...SYNERGY_BONUSES },
  'wp_hanok:maehwa':    { label: '한옥 × 매화',      ...SYNERGY_BONUSES },
  'wp_lake:archieve':   { label: '호수 × 아카이브',  ...SYNERGY_BONUSES },
