  ...SYNERGY_BONUSES,
};

export function getSynergy(wpId: string | null, characterId: string): WallpaperSynergy | null {
  if (!wpId) return null;
  if (characterId === 'chibi') return CHIBI_SYNERGY;
  return SYNERGY_MAP[`${wpId}:${characterId}`] ?? null;
}

